'use strict';
(()=>{
const $=id=>document.getElementById(id),R=window.CenizasRules,Nav=window.CenizasNavigation,Dice=window.CenizasDice,Cinema=window.CenizasBattleScene,KEY='cenizas-campaign-v2';
let state=R.fresh(),character=R.defaults,storageOK=true,scene=null,battle=null,ready=false,moveAt=0,autoAt=0,toastTimer,focused=true;
try{const s=JSON.parse(localStorage.getItem(KEY));if(R.valid(s))state=s;const c=JSON.parse(localStorage.getItem('cenizas-character-v1'));if(c&&Array.isArray(c.base))character=c;}catch{}
let heroProfile=R.profile(character,state.level);
state.hp=state.hp===null?heroProfile.max:Math.max(0,Math.min(heroProfile.max,Number(state.hp)||0));state.spells=state.spells===null?heroProfile.spells:Math.max(0,Math.min(heroProfile.spells,Number(state.spells)||0));
const stick=window.createJoystick($('joystick'),$('joystick-knob')),held=new Set();
const rooms={
 plaza:{name:'La plaza de Valdara',img:'scenes/plaza.png',start:[770,770],obstacles:[{x:730,y:640,rx:155,ry:90}],poly:[[420,470],[930,450],[1200,675],[1000,870],[530,900],[340,690]],spots:[['maela','Maela',520,610],['depot','Depósito',1100,650],['taller','Taller de Ordan',860,500],['bridge','Volver al puente',480,780]]},
 taller:{name:'El taller del silencio',img:'scenes/taller.png',start:[680,620],poly:[[460,440],[835,390],[1100,545],[950,690],[580,810],[360,590]],spots:[['ordan','Ordan',620,540],['rest','Descansar',500,620],['crypt','Bajar a las criptas',790,710],['plaza','Volver a la plaza',980,565]]},
 criptas:{name:'Las criptas del río',img:'scenes/criptas.png',start:[760,690],poly:[[430,490],[700,460],[1150,560],[1150,700],[930,795],[580,755],[370,610]],spots:[['guard','Puesto de la Vigilia',530,615],['register','Registro y compuerta',790,545],['taller','Subir al taller',1080,650]]},
 bosque:{name:'Bosque de los Susurros',img:'scenes/bosque.png',start:[655,710],poly:[[260,650],[570,520],[730,520],[990,660],[1200,650],[1390,790],[950,915],[700,850],[450,860]],spots:[['echo','La voz entre las raíces',560,620],['elara','Hablar con Elara',760,650],['trail','Camino del monasterio',1170,760],['plaza','Regresar a Valdara',470,760]]}
};
const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const modal=()=>!!document.querySelector('dialog[open]');
function save(){if(battle)state.combat=battle.s;try{localStorage.setItem(KEY,JSON.stringify(state));$('saved').textContent='Guardado en este dispositivo';storageOK=true;}catch{storageOK=false;$('saved').textContent='No se pudo guardar';}}
function note(t){state.log.push(t);state.log=state.log.slice(-100);save();}
function toast(t){$('toast').textContent=t;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),3600);}
function stop(){stick.reset();held.clear();scene?.hero?.anims.stop();}
function open(id){stop();$(id).showModal();}
function close(id){$(id).close();stop();autoAt=performance.now()+1100;}
function say(who,text,options=[['Continuar',()=>{}]]){stop();$('voice').textContent=rooms[state.place].name.toUpperCase();$('speaker').textContent=who;$('speech').textContent=text;$('choices').replaceChildren(...options.map(([label,fn])=>{const b=document.createElement('button');b.textContent=label;b.onclick=()=>{close('story');fn();};return b;}));if(!$('story').open)open('story');}
function paper(title,html){$('paper-title').textContent=title;$('paper-content').innerHTML=html;open('paper');}
function roll(sides=20){const a=new Uint32Array(1),limit=Math.floor(4294967296/sides)*sides;do{crypto.getRandomValues(a)}while(a[0]>=limit);return a[0]%sides+1;}
function skill(index,ability){const base=character.base||R.defaults.base;let total=(Number(character.ranks?.[index])||0)+Math.floor((base[ability]-10)/2);if(character.race==='Enano'&&ability===5)total--;if(character.race==='Elfo'&&[3,4,13].includes(index))total+=2;return total;}
async function skillCheck(name,index,ability,dc){const key=name+':'+index+':'+dc;state.rollResults=state.rollResults||{};const bonus=skill(index,ability),previous=state.rollResults[key];stop();const result=await Dice.show({title:name,detail:`d20 ${bonus>=0?'+':''}${bonus} contra CD ${dc}. Puedes retirarte antes de tirar.`,optional:!previous,auto:!!previous,resolve:()=>{if(previous)return previous;const die=roll(),ok=die+bonus>=dc,text=`${name}: ${die} ${bonus>=0?'+':''}${bonus} = ${die+bonus} · CD ${dc} · ${ok?'Éxito':'Fallo'}`;const q={dice:[{sides:20,value:die}],summary:text,ok,text};state.rollResults[key]=q;note(text);return q;}});return result;}
async function opposedCheck(){state.rollResults=state.rollResults||{};const previous=state.rollResults.depot,bonus=skill(9,5);stop();return Dice.show({title:'Engañar al encargado',detail:`Tu d20 ${bonus>=0?'+':''}${bonus} contra su d20 +2. Puedes retirarte sin intentarlo.`,optional:!previous,auto:!!previous,resolve:()=>{if(previous)return previous;let a=roll(),b=roll();const dice=[{sides:20,value:a,label:'Tu d20'},{sides:20,value:b,label:'Encargado'}];let success=a+bonus>b+2||(a+bonus===b+2&&bonus>2);let summary=`Tu tirada: ${a} ${bonus>=0?'+':''}${bonus} = ${a+bonus}\nEncargado: ${b} +2 = ${b+2}`;if(a+bonus===b+2&&bonus===2){do{a=roll();b=roll();dice.push({sides:20,value:a,label:'Tu desempate'},{sides:20,value:b,label:'Su desempate'});}while(a===b);success=a>b;summary+='\nDesempate: '+a+' contra '+b;}summary+='\n'+(success?'Éxito':'Fallo');const q={dice,summary,success};state.rollResults.depot=q;note(summary);return q;}});}
function showCombatRolls(title='Tirada de combate'){if(!battle?.rolls.length)return;const dice=battle.rolls.splice(0),summary=battle.events.splice(0).join('\n');stop();Dice.show({title,detail:'Tirada obligatoria del encuentro. La acción ya está resuelta; estos son sus dados.',auto:true,combat:true,resolve:()=>({dice,summary})});}
function objective(){if(state.flags.forest)return 'Camino despejado · revisar el diario';if(state.flags.elara)return 'Cruzar el bosque con Elara';if(state.flags.custodian)return 'Volver a la plaza y hablar con Elara';if(state.flags.workshop)return 'Investigar el registro bajo el río';if(state.flags.branchDone)return 'Buscar respuestas con Ordan';if(state.branch)return state.branch==='maela'?'Proteger a los testigos con Maela':'Investigar el depósito';return 'Hablar con Maela sobre los desaparecidos';}
function hud(){window.CenizasMusic?.set(state.place,!!battle);$('name').textContent=heroProfile.name;$('level').textContent=state.level;$('hp').textContent=`${battle?battle.hero.hp:state.hp} / ${heroProfile.max} PG · ${heroProfile.class}`;$('place').textContent=rooms[state.place].name;$('chapter-label').textContent=state.place==='bosque'?'CAPÍTULO II':'CAPÍTULO I';$('quest').textContent=objective()+' ›';}
function refreshCharacter(){try{const c=JSON.parse(localStorage.getItem('cenizas-character-v1'));if(c&&Array.isArray(c.base))character=c;}catch{}const old=heroProfile;heroProfile=R.profile(character,state.level);state.hp=Math.max(1,Math.min(heroProfile.max,state.hp+(heroProfile.max-old.max)));state.spells=Math.min(heroProfile.spells,state.spells);hud();save();}
function item(name){if(!state.items.includes(name))state.items.push(name);}
function travel(place){if(battle)return;if(place==='plaza'&&state.flags.custodian&&!state.flags.elara){state.place='plaza';state.position=null;scene.enter();reunion();return;}if(place==='taller'&&!state.flags.branchDone){toast('Primero resuelve la situación de los testigos.');return;}if(place==='criptas'&&!state.flags.workshop){toast('Habla con Ordan y resuelve el eco del taller.');return;}if(place==='bosque'&&!state.flags.elara){toast('Elara te espera en la plaza.');return;}state.place=place;state.position=null;scene.enter();save();}
async function interact(id){if(!ready||battle||modal())return;
if(id==='bridge'){save();location.href='index.html';return;}
if(['plaza','taller'].includes(id)){travel(id);return;}
if(id==='maela'){
 if(state.flags.custodian){if(!state.flags.elara)reunion();else say('Maela','Los documentos están a salvo. Elara te espera para continuar hacia el bosque.',[['Ir al bosque',()=>travel('bosque')],['Quedarme en Valdara',()=>{}]]);return;}
 if(!state.branch){say('Maela','Otra familia busca a alguien que la Orden dice que nunca vivió aquí. Necesito reunir a quienes lo recuerdan. El escriba está llevando los avisos al depósito: si lo sigues ahora, quizá encuentres pruebas.',[['Proteger a los testigos con Maela',()=>{state.branch='maela';save();interact('maela');}],['Seguir los documentos al depósito',()=>{state.branch='depot';save();toast('Investiga el depósito al este de la plaza.');hud();}]]);return;}
 if(state.flags.branchDone){say('Maela','Ordan, el campanero, puede reconocer ese sello. Su taller está al fondo de la plaza.');return;}
 if(state.branch==='depot'){say('Maela','Yo me quedaré con las familias. Sigue los avisos antes de que desaparezcan.');return;}
 say('Maela','Los vecinos temen dar sus nombres. Puedes explicarles por qué su testimonio importa. Diplomacia CD 15; fallar no impide conservar el primer testimonio.',[['Pedir que permanezcan juntos · Diplomacia',async()=>{const q=await skillCheck('Diplomacia',8,5,15);if(!q)return;state.flags.witnesses=q.ok;state.flags.branchDone=true;state.potions+=q.ok?1:0;item('Testimonio de los vecinos');save();hud();say('Los nombres que quedan',q.text+'\n\n'+(q.ok?'Los vecinos se organizan. Maela te entrega una poción y promete ayudar en la evacuación.':'Varios vecinos se retiran, pero Maela conserva el primer testimonio. Ordan puede ayudarte igualmente.'),[['Buscar a Ordan',()=>travel('taller')]]);}]]);return;
}
if(id==='depot'){
 if(state.branch!=='depot'){say('Depósito municipal',state.branch?'Elegiste quedarte con los vecinos. El escriba ya trasladó los documentos.':'Maela, junto a la fuente, necesita hablar contigo.');return;}
 if(state.flags.branchDone){say('Depósito municipal','Ya conservaste la información que pudiste recuperar. Ordan espera en su taller.');return;}
 say('La tinta del silencio','El encargado ordena los avisos junto a una copia del sello. Puedes fingir que llevas una orden de revisión. Engañar contra Averiguar intenciones +2; fallar conserva la pista básica.',[['Intentar recuperar la orden · Engañar',async()=>{const q=await opposedCheck();if(!q)return;const success=q.success;state.flags.seal=success;state.flags.branchDone=true;item(success?'Orden de traslado sellada':'Copia parcial de los traslados');save();hud();say('Un rastro de tinta',success?'La orden confirma que los trasladados pasan por las criptas. Su sello permitirá evitar al guardia.':'El encargado te descubre y oculta la orden. Alcanzas a leer la referencia a las criptas; conservas una copia parcial.',[['Ir al taller de Ordan',()=>travel('taller')]]);}]]);return;
}
if(id==='ordan'){
 if(state.flags.workshop){say('Ordan','La campana no está llamando a los muertos. Alguien la alimenta con nombres. Baja a las criptas y recupera el registro. Yo abriré el mantenimiento de la compuerta. Puedes descansar aquí antes de bajar.',[['Bajar a las criptas',()=>travel('criptas')],['Descansar',()=>rest()]]);return;}
 say('Ordan','La cera sigue caliente… Darien vino con una advertencia parecida. Hay algo conectado al río. ¡Atrás! La ceniza del conducto está tomando forma.',[['Prepararme para el encuentro',()=>say('Primer combate','Cada turno tiene una acción y movimiento. Usa las flechas para moverte por las casillas. Los ataques precisos dan +2 al ataque; puedes esquivar o parar los golpes enemigos. Puedes atacar al eco o alcanzar la válvula verde y cerrarla. El diario y los menús pausan el combate.',[['Comenzar',()=>startBattle('echo')]])],['Revisar mi personaje',()=>sheet()]]);return;
}
if(id==='rest'){rest();return;}
if(id==='crypt'){travel('criptas');return;}
if(id==='guard'){
 if(state.flags.guard){say('Puesto de la Vigilia','El acceso está despejado. El registro se encuentra junto a la compuerta.');return;}
 if(state.flags.seal){state.flags.guard=true;save();say('Guardia de la Vigilia','La orden lleva el sello correcto. Puedes revisar el registro. Yo no he visto nada.',[['Continuar',()=>hud()]]);return;}
 say('Guardia de la Vigilia','Sin una orden no puedo dejarte revisar las listas. Si quieres insistir, tendrás que explicar a quién estás buscando.',[['Hablar de Darien y los desaparecidos',()=>{state.flags.guard=true;note('El guardia permitió revisar el registro al oír el nombre de Darien.');say('Guardia de la Vigilia','Ese nombre sí lo recuerdo. No deberían haberlo borrado. Revisa la compuerta; si alguien pregunta, estabas ayudando a Ordan.');}],['Retirarme por ahora',()=>{}]]);return;
}
if(id==='register'){
 if(!state.flags.guard){toast('Habla primero con el guardia del puesto.');return;}
 if(state.flags.custodian){say('La compuerta abierta','El registro confirma traslados hacia el Monasterio de Ceniza. Elara necesita verlo.',[['Volver a la plaza',()=>travel('plaza')]]);return;}
 const intro=()=>say('El Custodio de la compuerta','Al tocar el registro, la piedra despierta. Ordan señala dos ruedas: cerrarlas apagará al guardián. Sus golpes se anuncian en rojo y se resuelven en su siguiente turno. Puedes salir de la casilla marcada, cerrar ambas ruedas o derrotarlo.',[['Enfrentar al Custodio',()=>startBattle('custodian')],['Volver a prepararme al taller',()=>travel('taller')]]);
 if(!state.flags.searched){const q=await skillCheck('Buscar',4,3,12);if(!q)return;state.flags.searched=true;state.flags.conduitHint=q.ok;save();say('Bajo el río',q.text+'\n\n'+(q.ok?'Encuentras el conducto defectuoso antes de retirar el registro. Podrás golpearlo para interrumpir una carga.':'Las notas de Darien siguen junto al registro: indican las dos ruedas de cierre. Ordan te explicará el conducto cuando se ilumine.'),[['Retirar el registro',intro]]);}else intro();return;
}
if(id==='echo'){
 if(state.flags.forest){say('El bosque vuelve a respirar','La voz se apagó. El sendero hacia el monasterio queda despejado.');return;}
 say('Elara','Esa voz repite las mismas palabras. Mi hermano respondería a una pregunta nueva. Vamos juntos: puedes darme órdenes en mi turno o pedirme que actúe con una táctica.',[['Avanzar juntos',()=>startBattle('whisper')],['Revisar el grupo',()=>inventory()]]);return;
}
if(id==='elara'){say('Elara',state.flags.forest?'Cuando esa cosa imitó a Darien, casi le creí. Gracias por quedarte. Ahora sabemos hacia dónde seguir.':'Una voz conocida no siempre dice la verdad. Sigamos el camino y comprobemos lo que encontramos.',[['Revisar control de Elara',()=>inventory()],['Continuar',()=>{}]]);return;}
if(id==='trail'){if(!state.flags.forest){toast('Resuelve primero la aparición entre las raíces.');return;}say('El monasterio, a lo lejos','Aquí termina este tramo jugable. Conservas el nivel 2, el botín, las decisiones de Valdara y el control de Elara. La entrada al monasterio será el siguiente tramo.',[['Revisar el diario',()=>journal()],['Seguir explorando',()=>{}]]);}
}
function rest(){if(battle)return;say('Un descanso en el taller','Ordan cierra el acceso mientras descansas. Recuperarás los puntos de golpe y la preparación de magia; las pociones no se reponen.',[['Descansar hasta estar listo',()=>{state.hp=heroProfile.max;state.spells=heroProfile.spells;state.elaraHP=16;save();hud();toast('Descanso completo · PG y magia recuperados.');}],['Todavía no',()=>{}]]);}
function reunion(){state.flags.elara=true;save();say('Elara','Darien está en esas listas. Iré contigo al bosque. Maela conservará una copia y Ordan buscará una ruta de servicio. No dejaremos que vuelvan a borrar a nadie.',[['Partir con Elara',()=>travel('bosque')],['Prepararme antes de partir',()=>{}]]);}
function startBattle(kind){if(battle)return;const checkpoint=JSON.parse(JSON.stringify(state));delete checkpoint.checkpoint;checkpoint.combat=null;state.checkpoint=checkpoint;battle=new R.Battle(kind,heroProfile,state);state.combat=battle.s;stop();$('battle').hidden=false;document.body.classList.add('fighting');autoAt=performance.now()+1000;renderBattle();save();showCombatRolls('Iniciativa');}
function renderBattle(){if(!battle)return;const s=battle.s,a=battle.actor;hud();$('turn').textContent=s.result==='victory'?'Encuentro resuelto':s.result==='defeat'?'El viaje se interrumpe':`${a.name} · ronda ${s.round}`;$('economy').textContent=s.result?'':`${s.action?'1 acción disponible':'Acción utilizada'} · ${s.movement} casillas de movimiento`;
 const warning=s.warning;$('warning').textContent=warning?(warning.type==='pulse'?`Descarga anunciada: fila ${warning.y+1}. Sal antes del próximo turno enemigo.`:'Puño anunciado: abandona la casilla roja.'):(s.kind==='echo'?'La válvula verde disipa al eco. Cada casilla son 1,5 m.':s.kind==='custodian'?'Cierra las dos ruedas verdes o derrota al Custodio.':'Muévete con las flechas. Puedes flanquear al eco con Elara.');
 $('board').replaceChildren();for(let y=0;y<5;y++)for(let x=0;x<7;x++){const cell=document.createElement('div');cell.className='cell';cell.setAttribute('role','gridcell');cell.setAttribute('aria-label',`Fila ${y+1}, columna ${x+1}`);const hazard=warning&&(warning.type==='pulse'?y===warning.y:x===warning.x&&y===warning.y);if(hazard)cell.classList.add('danger');let mechanism=null;if(s.kind==='echo'&&x===5&&y===1)mechanism='Válvula';if(s.kind==='custodian'&&y===1&&(x===0||x===6))mechanism=s.wheels.includes(x===0?0:1)?'✓ Cerrada':'Rueda';if(mechanism){cell.classList.add('mechanism');const text=document.createElement('small');text.textContent=mechanism;cell.append(text);}
 for(const u of s.units.filter(u=>u.x===x&&u.y===y)){const unit=document.createElement('div');unit.className='unit'+(a.id===u.id?' active':'')+(u.hp<=0?' down':'');if(u.id==='hero'){const sprite=document.createElement('div');sprite.className='hero-sprite';unit.append(sprite);}else{const img=document.createElement('img');img.src=u.id==='elara'?'guard.png':s.kind==='custodian'?'custodian.png':'echo.png';img.alt=u.name;unit.append(img);}const label=document.createElement('small');label.textContent=`${u.id==='hero'?'Tú ':u.id==='elara'?'Elara ':''}${u.hp}/${u.max}`;unit.append(label);cell.append(unit);} $('board').append(cell);}
 $('party-status').textContent=s.units.filter(u=>u.team==='party').map(u=>`${u.name}: ${u.hp}/${u.max} PG`).join(' · ');
 document.querySelectorAll('[data-step]').forEach(b=>b.disabled=!!s.result||a.team!=='party'||(a.id==='elara'&&state.elaraMode==='auto')||s.movement<1);
 const elaraTurn=a.id==='elara'&&!s.result;$('elara-controls').hidden=!elaraTurn;$('control-mode').textContent=state.elaraMode==='auto'?'Tomar control manual':'Modo automático';$('tactic').value=state.tactic;
 const controls=$('combat-actions');controls.replaceChildren();function button(label,fn,disabled=false){const b=document.createElement('button');b.textContent=label;b.disabled=disabled;b.onclick=fn;controls.append(b);}
 if(s.result){button(s.result==='victory'?'Continuar':'Volver al punto seguro',finishBattle);return;}
 const playable=a.team==='party'&&!(a.id==='elara'&&state.elaraMode==='auto');
 button('Atacar',()=>act('attack'),!playable||!s.action||R.distance(a,battle.enemy)!==1);
 if(a.power)button('Ataque poderoso',()=>act('power'),!playable||!s.action||R.distance(a,battle.enemy)!==1);
 if(a.class==='Mago'){button(`Proyectil (${s.spells})`,()=>act('missile'),!playable||!s.action||s.spells<1);button('Armadura mágica',()=>act('armor'),!playable||!s.action||!s.spells||s.spellArmor);}
 if(s.kind!=='whisper')button(s.kind==='echo'?'Cerrar válvula':'Cerrar rueda',()=>act('mechanism'),!playable||!s.action);
 if(s.kind==='custodian'&&!s.exposed)button('Golpear conducto',()=>act('conduit'),!playable||!s.action||R.distance(a,battle.enemy)!==1);
 button(`Poción (${s.potions})`,()=>act('potion'),!playable||!s.action||s.potions<1||a.hp>=a.max);button('Defender',()=>act('guard'),!playable||!s.action);button('Terminar turno',()=>{battle.end();after();},!playable);
}
async function cinematicAction(title,defense,resolve,optional=true){stop();const current=battle;const q=await Cinema.show({title,room:state.place,kind:battle.s.kind,party:defense?'hero':battle.actor.id,defense,optional,resolve:options=>{current.rolls.length=0;current.events.length=0;resolve(options);save();return {dice:current.rolls.splice(0),summary:current.events.splice(0).join('\n')};}});if(q){renderBattle();await Dice.show({title:'Resultado de la acción',auto:true,combat:true,resolve:()=>q});after();}}
async function enemyAction(){if(!battle||modal())return;const s=battle.s;const threat=s.kind==='custodian'?!!s.warning&&!s.cancelNext:!s.opening;if(threat){await cinematicAction('Defensa activa',true,o=>battle.enemyTurn(o),false);}else{battle.enemyTurn();after();}}
async function act(kind){if(!battle||modal())return;if(['attack','power','missile'].includes(kind)){await cinematicAction(kind==='missile'?'Proyectil mágico':'Ataque de '+battle.actor.name,false,o=>battle.act(kind,o));return;}const names={attack:'Ataque',power:'Ataque poderoso',missile:'Proyectil mágico',potion:'Poción de curación',conduit:'Golpear el conducto'};if(!names[kind]){battle.act(kind);after();return;}stop();const result=await Dice.show({title:names[kind],combat:true,detail:'Confirma la acción para tirar. Puedes salir ahora sin gastar tu acción ni recursos.',optional:true,resolve:()=>{battle.rolls.length=0;battle.events.length=0;battle.act(kind);save();return {dice:battle.rolls.splice(0),summary:battle.events.splice(0).join('\n')};}});if(result)after();}
function after(){renderBattle();save();autoAt=performance.now()+1100;const last=battle?.s.history.at(-1);if(last)toast(last);showCombatRolls();}
function finishBattle(){if(!battle?.s.result)return;const s=battle.s;state.log.push(...s.history);state.log=state.log.slice(-100);
 if(s.result==='defeat'){const checkpoint=state.checkpoint;state=checkpoint&&R.valid(checkpoint)?checkpoint:R.fresh();battle=null;state.combat=null;heroProfile=R.profile(character,state.level);$('battle').hidden=true;document.body.classList.remove('fighting');scene.enter();save();hud();toast('Regresas al inicio del encuentro con los recursos anteriores.');return;}
 state.hp=battle.hero.hp;state.spells=s.spells;state.potions=s.potions;state.elaraHP=s.units.find(u=>u.id==='elara')?.hp??state.elaraHP;state.combat=null;delete state.checkpoint;battle=null;$('battle').hidden=true;document.body.classList.remove('fighting');
 if(s.kind==='echo'){state.flags.workshop=true;item('Residuo de ceniza fría');note('El taller quedó seguro. Ordan abrió el paso a las criptas.');say('Ordan','Eso no era una persona. Solo repetía lo que había oído. La fuente está bajo el río. Descansa aquí y revisa el registro de la compuerta.',[['Descansar',rest],['Bajar a las criptas',()=>travel('criptas')]]);}
 if(s.kind==='custodian'){state.flags.custodian=true;state.level=2;heroProfile=R.profile(character,2);state.hp=heroProfile.max;state.spells=heroProfile.spells;state.gold+=15;state.potions++;item('Registro de traslados');item('Abrazadera de compuerta');note('Nivel 2. Recuperaste el registro, 15 po y una poción.');say('La guardia elige','La compuerta se detiene. El registro nombra a Darien y al Monasterio de Ceniza. Alcanzas nivel 2: aumentan tus PG y capacidades. Puedes repartir los nuevos puntos en la hoja de personaje.',[['Volver con Elara',()=>travel('plaza')],['Revisar nivel 2',()=>sheet()]]);}
 if(s.kind==='whisper'){state.flags.forest=true;state.elaraHP=Math.max(1,state.elaraHP);item('Residuo del bosque');note('Elara y el protagonista despejaron juntos el primer sendero.');say('Elara','Cuando intentó repetir mi voz, ya estabas a mi lado. Esa cosa no puede inventar un recuerdo. El monasterio está al otro lado del bosque.',[['Ver el camino',()=>{}],['Revisar el diario',journal]]);}
 hud();save();}
function journal(){paper('Diario del viajero',`<p><b>${esc(objective())}</b></p><ol class="paper-list"><li>La carta sellada · puente de Valdara.</li><li>${state.flags.branchDone?'✓':'○'} ${state.branch==='depot'?'La tinta del silencio':'Los nombres que quedan'}.</li><li>${state.flags.workshop?'✓':'○'} El taller del silencio.</li><li>${state.flags.custodian?'✓':'○'} El Custodio de la compuerta.</li><li>${state.flags.elara?'✓':'○'} Elara se une al viaje.</li><li>${state.flags.forest?'✓':'○'} La primera voz del bosque.</li></ol><p>${state.flags.witnesses?'Los testigos protegidos ayudarán en la evacuación del monasterio.':state.flags.seal?'La orden sellada permitió evitar el interrogatorio de las criptas.':'Las pistas esenciales se conservan aunque fallen las pruebas.'}</p><p class="muted">Tramo disponible: Valdara, taller, criptas y primera aparición del bosque. El monasterio todavía no está abierto.</p><div class="logs">${state.log.slice(-8).map(t=>`<p>${esc(t)}</p>`).join('')}</div>`);}
function inventory(){paper('Personaje y mochila',`<p><b>${esc(heroProfile.name)}</b> · ${esc(heroProfile.class)} · Nivel ${state.level}</p><div class="stats"><div><b>${state.hp}/${heroProfile.max}</b><small>PG</small></div><div><b>${heroProfile.ac}</b><small>CA</small></div><div><b>${state.gold}</b><small>Oro</small></div></div><p>Pociones: ${state.potions} · Cura 1d8+1 PG.</p>${heroProfile.class==='Mago'?`<p>Preparación arcana disponible: ${state.spells}/${heroProfile.spells}. En este tramo puedes usar Proyectil mágico y Armadura de mago.</p>`:''}<ul>${state.items.map(x=>`<li>${esc(x)}</li>`).join('')||'<li>Carta sellada y equipo inicial.</li>'}</ul>${state.flags.elara?`<p><b>Elara</b> · ${state.elaraHP}/16 PG · CA 16. Control combinado: al llegar su turno puedes dar órdenes, activar una táctica o cambiar a automático. Si cae, queda fuera del encuentro; al vencer se recupera con 1 PG.</p>`:''}<button id="drink" ${state.potions<1||state.hp>=heroProfile.max?'disabled':''}>Beber una poción</button> <button id="edit-character">Abrir hoja completa</button><p class="muted">Armas y armadura: equipo inicial de la clase. No hay compra ni venta en este tramo.</p>`);$('drink').onclick=async()=>{stop();const q=await Dice.show({title:'Beber una poción',detail:'Cura 1d8+1 PG. Puedes salir antes de tirar sin consumir la poción.',optional:true,resolve:()=>{const d=roll(8),n=d+1;state.hp=Math.min(heroProfile.max,state.hp+n);state.potions--;const summary=`Poción: ${d} +1 = ${n} PG de curación. Salud: ${state.hp}/${heroProfile.max}.`;note(summary);return {dice:[{sides:8,value:d}],summary};}});if(q){close('paper');inventory();hud();}};$('edit-character').onclick=()=>{close('paper');sheet();};}
function map(){const available={plaza:true,taller:state.flags.branchDone,criptas:state.flags.workshop,bosque:state.flags.elara};paper('Tierras de Valdara',`<p><b>Estás en: ${esc(rooms[state.place].name)}</b></p><img class="region-picture" src="region-map.png" alt="Mapa regional de Valdara, el bosque y las montañas"><div class="travel">${Object.entries(rooms).map(([id,r])=>`<button data-travel="${id}" ${!available[id]?'disabled':''}>${id===state.place?'◆ ':''}${esc(r.name)}</button>`).join('')}<button disabled>Monasterio · próximo tramo</button><button disabled>El Umbral · más adelante</button></div><p class="muted">Viaje entre lugares descubiertos. Dentro de cada paisaje, usa el joystick.</p>`);document.querySelectorAll('[data-travel]').forEach(b=>b.onclick=()=>{close('paper');travel(b.dataset.travel);});}
function sheet(){if(battle)return;$('sheet-frame').src='character.html?campaign=1';open('sheet');}
function inside(x,y,poly){let hit=false;for(let i=0,j=poly.length-1;i<poly.length;j=i++){const a=poly[i],b=poly[j];if(((a[1]>y)!==(b[1]>y))&&x<(b[0]-a[0])*(y-a[1])/(b[1]-a[1])+a[0])hit=!hit;}return hit;}
class CampaignScene extends Phaser.Scene{
 constructor(){super('Campaign');}
 preload(){for(const [key,r]of Object.entries(rooms))this.load.image(key,r.img);this.load.image('traveler','hero-sprites.png');this.load.image('elara','guard.png');this.failed=false;this.load.on('loaderror',()=>{this.failed=true;$('loading').textContent='No se pudo cargar un paisaje. Recarga para intentarlo nuevamente.';});}
 create(){if(this.failed)return;scene=this;this.layer=this.add.container(0,0);const t=this.textures.get('traveler'),src=t.getSourceImage();for(let y=0;y<4;y++)for(let x=0;x<4;x++)t.add(y*4+x,0,Math.round(x*src.width/4),Math.round(y*src.height/4),Math.round(src.width/4),Math.round(src.height/4));for(let y=0;y<4;y++)this.anims.create({key:'walk'+y,frames:[0,1,2,3].map(x=>({key:'traveler',frame:y*4+x})),frameRate:7,repeat:-1});this.bg=this.add.image(0,0,state.place).setOrigin(0).setDisplaySize(1536,1024);this.hero=this.add.sprite(0,0,'traveler',8).setOrigin(.5,.96).setDisplaySize(88,88);this.ally=this.add.image(0,0,'elara').setOrigin(.5,.98).setDisplaySize(93,93);this.labels=[];this.cameras.main.setBounds(0,0,1536,1024);this.cameras.main.startFollow(this.hero,true,.12,.12);this.scale.on('resize',()=>this.resize());this.resize();ready=true;this.enter();$('loading').hidden=true;
 if(state.combat){try{if(!Array.isArray(state.combat.units)||!Array.isArray(state.combat.order)||!state.combat.units.some(u=>u.id==='hero'))throw Error();battle=new R.Battle(state.combat.kind,heroProfile,state);if(!battle.actor)throw Error();$('battle').hidden=false;document.body.classList.add('fighting');renderBattle();autoAt=performance.now()+1600;}catch{state.combat=null;battle=null;save();}}
 if(!state.flags.intro&&!battle){state.flags.intro=true;save();say('Valdara abre sus puertas','El centinela reconoce tu nombre. En la plaza, una boticaria discute con un escriba. La cera de tu carta sigue caliente. Acércate a Maela con el joystick o las flechas.',[['Explorar la plaza',()=>{}],['Revisar mi personaje',sheet]]);}}
 resize(){this.cameras.main.setZoom(Math.max(.62,Math.min(1.3,Math.max(this.scale.width/1536,this.scale.height/1024))));stop();}
 enter(){stop();const r=rooms[state.place];this.bg.setTexture(state.place);const safe=Nav.safe(r,state.position),p=[safe.x,safe.y];state.position=safe;this.trail=[safe];this.ally.setPosition(safe.x,safe.y);this.hero.setPosition(...p);this.cameras.main.centerOn(...p);this.labels.forEach(x=>x.destroy());this.labels=r.spots.map(([id,label,x,y])=>{const t=this.add.text(x,y-30,label+' ›',{fontFamily:'Georgia',fontSize:'18px',color:'#fff1c3',backgroundColor:'#18362bda',padding:{x:9,y:6},stroke:'#173426',strokeThickness:1}).setOrigin(.5).setDepth(2000).setInteractive({useHandCursor:true});t.on('pointerdown',()=>{if(Math.hypot(this.hero.x-x,this.hero.y-y)>130||!Nav.clear(r,this.hero,{x,y}))toast('Acércate con el joystick para interactuar.');else interact(id);});return t;});this.ally.setVisible(!!state.flags.elara);hud();}
 update(_t,dt){if(!ready||modal()||document.hidden||!focused)return;let dx=(held.has('ArrowRight')||held.has('d')?1:0)-(held.has('ArrowLeft')||held.has('a')?1:0),dy=(held.has('ArrowDown')||held.has('s')?1:0)-(held.has('ArrowUp')||held.has('w')?1:0);if(!battle&&!dx&&!dy){dx=stick.state.x;dy=stick.state.y;}const now=performance.now();
 if(battle){const a=battle.actor;if(battle.s.result)return;if(a.team==='enemy'&&now>=autoAt){enemyAction();return;}if(a.id==='elara'&&state.elaraMode==='auto'&&now>=autoAt){battle.auto(state.tactic);after();return;}if(a.team==='party'&&!(a.id==='elara'&&state.elaraMode==='auto')&&now>moveAt&&Math.hypot(dx,dy)>.25){const mx=Math.abs(dx)>Math.abs(dy)?Math.sign(dx):0,my=mx?0:Math.sign(dy);if(battle.move(mx,my)){renderBattle();save();}moveAt=now+230;}return;}
 let moving=false;const length=Math.hypot(dx,dy);if(length){const speed=150*Math.min(dt,40)/1000;dx=dx/Math.max(1,length)*speed;dy=dy/Math.max(1,length)*speed;const room=rooms[state.place];if(Nav.walkable(room,this.hero.x+dx,this.hero.y+dy)){this.hero.x+=dx;this.hero.y+=dy;moving=true;}else if(Nav.walkable(room,this.hero.x+dx,this.hero.y)){this.hero.x+=dx;moving=true;}else if(Nav.walkable(room,this.hero.x,this.hero.y+dy)){this.hero.y+=dy;moving=true;}}
 if(moving){const dir=Math.abs(dx)>Math.abs(dy)?(dx>0?2:1):(dy>0?0:3);this.hero.play('walk'+dir,true);state.position={x:this.hero.x,y:this.hero.y};}else this.hero.anims.stop();this.hero.setDepth(this.hero.y);if(Math.hypot(this.hero.x-this.trail.at(-1).x,this.hero.y-this.trail.at(-1).y)>6){this.trail.push({x:this.hero.x,y:this.hero.y});if(this.trail.length>9)this.trail.shift();}const follow=this.trail[0];this.ally.setPosition(follow.x,follow.y).setDepth(follow.y);const near=rooms[state.place].spots.map(p=>({id:p[0],label:p[1],d:Nav.clear(rooms[state.place],this.hero,{x:p[2],y:p[3]})?Math.hypot(this.hero.x-p[2],this.hero.y-p[3]):Infinity})).sort((a,b)=>a.d-b.d)[0];this.nearest=near?.d<=130?near:null;$('interact').textContent=this.nearest?.label||'Acércate a un lugar';$('interact').disabled=!this.nearest;}
}
document.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>{if(!battle||modal()||battle.actor.team!=='party'||(battle.actor.id==='elara'&&state.elaraMode==='auto'))return;const [dx,dy]=b.dataset.step.split(',').map(Number);if(battle.move(dx,dy)){renderBattle();save();}});
$('interact').onclick=()=>scene?.nearest&&interact(scene.nearest.id);$('journal').onclick=journal;$('bag').onclick=inventory;$('quest').onclick=map;$('character').onclick=inventory;
$('battle-log').onclick=()=>paper('Tiradas del encuentro','<div class="logs">'+battle.s.history.slice(-30).map(t=>`<p>${esc(t)}</p>`).join('')+'</div>');
$('control-mode').onclick=()=>{state.elaraMode=state.elaraMode==='auto'?'manual':'auto';stop();autoAt=performance.now()+2000;renderBattle();save();};$('tactic').onchange=e=>{state.tactic=e.target.value;save();};$('auto').onclick=()=>{if(battle?.actor.id==='elara'){battle.auto(state.tactic);after();}};
$('help').onclick=()=>paper('Cómo jugar',`<p><b>Explorar:</b> joystick o flechas/WASD. Acércate a un nombre y pulsa Interactuar; tocar el suelo no mueve al personaje.</p><p><b>Combate:</b> cada casilla son 1,5 m. Las flechas en pantalla o del teclado mueven al personaje activo; el joystick se oculta. Una acción permite atacar, defender, usar magia, beber una poción o activar un mecanismo. Termina el turno cuando estés listo.</p><p><b>Precisión:</b> confirma el ataque y pulsa Golpear (o Espacio) cuando el indicador cruce la franja dorada: +2 al ataque o +1 de daño con Proyectil mágico. Ante un ataque enemigo, Esquivar reduce a la mitad el daño y Parar lo evita con una ventana más estrecha. Fallar conserva las tiradas normales. Puedes salir antes de confirmar un ataque; la defensa obligatoria no se cancela.</p><p><b>Elara:</b> en su turno puedes cambiar entre manual y automático sin gastar acciones. «Resolver automático» usa la táctica elegida solo para ese turno. Los cambios conservan lo que ya gastó.</p><p><b>Señales rojas:</b> el ataque se resolverá en el siguiente turno del jefe. Muévete a una casilla segura.</p><p><b>Pausa y guardado:</b> abrir un menú o salir de la app pausa la acción. El progreso se guarda en este navegador, incluso en combate.</p><p class="muted">Adaptación de D&D 3.5: sin ataques de oportunidad ni diagonales en este primer tramo; Armadura de mago dura el encuentro y la preparación usa una reserva compartida. La subida a nivel 2 usa PG fijos. Estas simplificaciones están indicadas para revisar el sistema antes de ampliar la campaña.</p>`);
$('full').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch{toast('Puedes girar el celular para ver más paisaje.');}};
document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>close(b.dataset.close));document.querySelectorAll('dialog').forEach(d=>d.addEventListener('close',()=>{stop();if(d.id==='sheet')refreshCharacter();autoAt=performance.now()+1300;}));window.addEventListener('message',e=>{if(e.origin===location.origin&&e.source===$('sheet-frame').contentWindow&&e.data?.type==='return-to-valdara')close('sheet');});
window.addEventListener('keydown',e=>{if(modal()||e.ctrlKey||e.metaKey||e.altKey||['SELECT','INPUT','TEXTAREA'].includes(e.target.tagName))return;const key=e.key.length===1?e.key.toLowerCase():e.key;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','w','a','s','d'].includes(key)){e.preventDefault();held.add(key);}if(key==='e'&&!e.repeat&&!battle&&scene?.nearest)interact(scene.nearest.id);});window.addEventListener('keyup',e=>held.delete(e.key.length===1?e.key.toLowerCase():e.key));window.addEventListener('blur',()=>{focused=false;stop();save();});window.addEventListener('focus',()=>{focused=true;autoAt=performance.now()+1300;});document.addEventListener('visibilitychange',()=>{stop();save();autoAt=performance.now()+1300;});window.addEventListener('pagehide',save);setInterval(()=>{if(!document.hidden)save();},3000);
hud();if(typeof Phaser==='undefined'){$('loading').textContent='No se pudo iniciar el juego. Recarga para intentarlo nuevamente.';return;}
new Phaser.Game({type:Phaser.AUTO,parent:'scene',backgroundColor:'#173329',scale:{mode:Phaser.Scale.RESIZE,width:innerWidth,height:innerHeight},render:{antialias:true},input:{activePointers:2},scene:CampaignScene,audio:{noAudio:true}});
})();
